package com.termux.view;
import android.app.Application;import android.graphics.*;import android.view.*;import com.termux.terminal.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.util.ReflectionHelpers;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class) public class TerminalHeaderInsetTest {
 static TerminalRenderer renderer(){TerminalRenderer r=new TerminalRenderer(14,Typeface.MONOSPACE);ReflectionHelpers.setField(r,"mFontLineSpacing",20);ReflectionHelpers.setField(r,"mFontLineSpacingAndAscent",15);ReflectionHelpers.setField(r,"mFontWidth",10f);return r;}
 @Test public void insetChangesRowsAndAllCoordinateTransformsTogether()throws Exception{TerminalView v=new TerminalView(RuntimeEnvironment.application,null);TerminalRenderer renderer=renderer();ReflectionHelpers.setField(v,"mRenderer",renderer);v.layout(0,0,360,700);java.lang.reflect.Method rows=TerminalView.class.getDeclaredMethod("rowsForView");rows.setAccessible(true);int before=(int)rows.invoke(v);int spacing=renderer.mFontLineSpacing;v.setHeaderTopInset(spacing*3);assertEquals(before-3,(int)rows.invoke(v));MotionEvent blank=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,10,10,0);assertFalse(v.onTouchEvent(blank));blank.recycle();MotionEvent e=MotionEvent.obtain(0,0,MotionEvent.ACTION_DOWN,10,spacing*3+renderer.mFontLineSpacingAndAscent+spacing*2,0);assertEquals(2,v.getColumnAndRow(e,false)[1]);e.recycle();assertEquals(spacing*5,v.getPointY(2));assertEquals(2,v.getCursorY(spacing*5+40));v.setHeaderTopInset(0);assertEquals(before,(int)rows.invoke(v));}
 @Test public void liveDrawingStartsBelowHeaderAndOlderRowsCanUseItsArea(){TerminalView v=new TerminalView(RuntimeEnvironment.application,null);TerminalEmulator em=new TerminalEmulator(new TerminalOutput(){public void write(byte[] b,int o,int n){}public void titleChanged(String a,String b){}public void onCopyTextToClipboard(String s){}public void onPasteTextFromClipboard(){}public void onBell(){}public void onColorsChanged(){}},20,4,10,20,2000,null);ReflectionHelpers.setField(v,"mEmulator",em);ReflectionHelpers.setField(v,"mRenderer",renderer());v.layout(0,0,360,700);v.setHeaderTopInset(70);class Surface extends Canvas{java.util.List<Float> shifts=new java.util.ArrayList<>();@Override public void translate(float x,float y){shifts.add(y);}}Surface surface=new Surface();v.onDraw(surface);assertTrue(surface.shifts.contains(70f));byte[] text="one\r\ntwo\r\nthree\r\nfour\r\nfive\r\nsix\r\n".getBytes(java.nio.charset.StandardCharsets.UTF_8);em.append(text,text.length);ReflectionHelpers.setField(v,"mTopRow",-1);surface.shifts.clear();v.onDraw(surface);assertTrue(surface.shifts.size()>=2);assertEquals(70,v.getHeaderTopInset());}
}
